arguments.new_str:
using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evals;

[TestClass]
public sealed class ChatEvals
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static IChatClient _chatClient = null!;
    private static ReportingConfiguration _reportingConfiguration = null!;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        var app = await _appHost.BuildAsync();
        await app.StartAsync();

        _chatClient = app.Services.GetRequiredService<IChatClient>();

        _reportingConfiguration = CreateReportingConfiguration();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (_appHost is IAsyncDisposable disposable)
        {
            await disposable.DisposeAsync();
        }
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var path = Path.Combine(Path.GetTempPath(), "MyApp.Evals", "reports");
        var storageFactory = (string storageName) => new DiskBasedReportingStorage(path);

        return new ReportingConfiguration(
            storageFactory,
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new GroundednessEvaluator(),
                new FluencyEvaluator(),
            ],
            chatClient: _chatClient);
    }

    [TestMethod]
    public async Task GreetingResponse_IsCoherentAndFluent()
    {
        await using var scenario = await _reportingConfiguration.CreateScenarioRunAsync(
            scenarioName: nameof(GreetingResponse_IsCoherentAndFluent));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how are you?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        EvaluationAssertions.AssertNoFailures(scenario);
    }

    [TestMethod]
    public async Task FactualQuestion_IsRelevantAndGrounded()
    {
        await using var scenario = await _reportingConfiguration.CreateScenarioRunAsync(
            scenarioName: nameof(FactualQuestion_IsRelevantAndGrounded));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        EvaluationAssertions.AssertNoFailures(scenario);
    }

    [TestMethod]
    public async Task ReasoningQuestion_MeetsQualityThresholds()
    {
        await using var scenario = await _reportingConfiguration.CreateScenarioRunAsync(
            scenarioName: nameof(ReasoningQuestion_MeetsQualityThresholds));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain why the sky is blue in simple terms.")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        EvaluationAssertions.AssertNoFailures(scenario);
    }
}

internal static class EvaluationAssertions
{
    public static void AssertNoFailures(ScenarioRun scenarioRun)
    {
        foreach (var result in scenarioRun.EvaluationResults)
        {
            foreach (var metric in result.Metrics)
            {
                if (metric.Value is NumericMetricValue numericValue)
                {
                    Assert.IsTrue(
                        numericValue.InterpretedValue != EvaluationRating.Unacceptable,
                        $"Metric '{metric.Key}' received an unacceptable rating.");
                }
            }
        }
    }
}

